@staticmethod
def _freeze_lifetime_value(value: object) -> object:
    """Return an isolated tuple/dict-only copy of a lifetime value."""
    if isinstance(value, dict):
        return {
            key: BranchStore._freeze_lifetime_value(item)
            for key, item in value.items()
        }
    if isinstance(value, (tuple, list)):
        return tuple(
            BranchStore._freeze_lifetime_value(item) for item in value
        )
    return value

@staticmethod
def _copy_lifetime_record(record: dict[str, object]) -> dict[str, object]:
    """Return an isolated copy of one lifetime record.

    The copy keeps the existing key order -- ``type, identity,
    first_seen, last_seen, intervals, transitions`` -- and shares no
    mutable object with the source record.
    """
    return {
        "type": record["type"],
        "identity": BranchStore._freeze_lifetime_value(
            record["identity"]
        ),
        "first_seen": record["first_seen"],
        "last_seen": record["last_seen"],
        "intervals": tuple(
            tuple(interval) for interval in record["intervals"]
        ),
        "transitions": tuple(
            {
                "kind": transition["kind"],
                "before": BranchStore._freeze_lifetime_value(
                    transition["before"]
                ),
                "after": BranchStore._freeze_lifetime_value(
                    transition["after"]
                ),
            }
            for transition in record["transitions"]
        ),
    }

@staticmethod
def _build_lifetime_churn_result(
    window_records: list[tuple[dict[str, object], ...]],
    segment_changes: list[tuple[dict[str, object], ...]],
    churn_limit_value: int | None,
) -> dict[str, object]:
    """Aggregate per-identity churn over every window and segment.

    Used only by :meth:`lifetime_churn`. Every node, edge and gap
    identity present in any window or touched by any adjacent
    segment gets one fresh record carrying the window positions it
    exists in, its addition/removal/change counters and, in segment
    order, one isolated ``from, to, kind, before, after`` entry per
    segment change. Records are visited deterministically -- windows
    in position order, each window in its node/edge/gap lifetime
    order, then change-only identities as the segments run -- and
    sorted by the counter sum descending, then the first presence
    position ascending (a change-only identity uses its first
    change's ``to``), then the existing type grouping and identity
    encounter order. The complete record set is built before the
    ``churn_limit`` cap is enforced, so an over-limit query raises
    :class:`ValueError` without returning partial records.
    """
    type_order = {"node": 0, "edge": 1, "gap": 2}
    present: dict[tuple[str, object], list[int]] = {}
    encounter: dict[tuple[str, object], int] = {}
    next_encounter = 0
    for position, lifetimes in enumerate(window_records):
        for record in lifetimes:
            key = (record["type"], record["identity"])
            if key not in present:
                present[key] = []
                encounter[key] = next_encounter
                next_encounter += 1
            present[key].append(position)

    added: dict[tuple[str, object], int] = {}
    removed: dict[tuple[str, object], int] = {}
    changed: dict[tuple[str, object], int] = {}
    identity_changes: dict[
        tuple[str, object], list[dict[str, object]]
    ] = {}
    first_change_to: dict[tuple[str, object], int] = {}
    for position, changes in enumerate(segment_changes):
        for change in changes:
            type_name = change["kind"].split("_", 1)[0]
            key = (type_name, change["identity"])
            if key not in encounter:
                encounter[key] = next_encounter
                next_encounter += 1
                first_change_to[key] = position + 1
            if change["kind"].endswith("_added"):
                added[key] = added.get(key, 0) + 1
            elif change["kind"].endswith("_removed"):
                removed[key] = removed.get(key, 0) + 1
            else:
                changed[key] = changed.get(key, 0) + 1
            before = change["before"]
            after = change["after"]
            identity_changes.setdefault(key, []).append(
                {
                    "from": position,
                    "to": position + 1,
                    "kind": change["kind"],
                    "before": (
                        None
                        if before is None
                        else BranchStore._copy_lifetime_record(before)
                    ),
                    "after": (
                        None
                        if after is None
                        else BranchStore._copy_lifetime_record(after)
                    ),
                }
            )

    ordered_keys = sorted(
        encounter,
        key=lambda key: (
            -(
                added.get(key, 0)
                + removed.get(key, 0)
                + changed.get(key, 0)
            ),
            present[key][0] if key in present else first_change_to[key],
            type_order[key[0]],
            encounter[key],
        ),
    )
    if len(ordered_keys) > churn_limit_value:
        raise ValueError(
            f"lifetime churn limit exceeded: {len(ordered_keys)} "
            f"identity records, limit is {churn_limit_value}"
        )

    total_added = 0
    total_removed = 0
    total_changed = 0
    records: list[dict[str, object]] = []
    for key in ordered_keys:
        type_name, identity = key
        added_count = added.get(key, 0)
        removed_count = removed.get(key, 0)
        changed_count = changed.get(key, 0)
        total_added += added_count
        total_removed += removed_count
        total_changed += changed_count
        records.append(
            {
                "type": type_name,
                "identity": BranchStore._freeze_lifetime_value(identity),
                "present": tuple(present.get(key, ())),
                "added": added_count,
                "removed": removed_count,
                "changed": changed_count,
                "changes": tuple(identity_changes.get(key, ())),
            }
        )
    return {
        "identities": tuple(records),
        "totals": {
            "identities": len(records),
            "added": total_added,
            "removed": total_removed,
            "changed": total_changed,
        },
    }

@staticmethod
def _build_lifetime_churn_streaks_result(
    segment_changes: list[tuple[dict[str, object], ...]],
    streak_limit_value: int | None,
) -> dict[str, object]:
    """Group each identity's churn into consecutive-segment streaks.

    Used only by :meth:`lifetime_churn_streaks`. Every node, edge and
    gap identity touched by an adjacent segment is followed across the
    segments in order; one change (added, removed or changed) on each
    of consecutive segments extends the same streak, while a segment
    without a change for that identity cuts it. A single changed
    segment is a streak on its own, so an identity present but
    unchanged in the first window never appears; being removed on one
    segment and re-added on the next stays one continuous streak.

    Identities keep the deterministic encounter order in which the
    segments' changes first name them. Each streak gets one fresh
    record with ordered keys ``type, identity, from, to, segments,
    added, removed, changed, changes``; ``from``/``to`` are the left
    window position of the streak's first segment and the right
    window position of its last, and ``changes`` keeps one isolated
    ``from, to, kind, before, after`` entry per segment. Records sort
    by total change count descending, then ``from`` and ``to``
    ascending, then the node, edge, gap grouping and identity
    encounter order. The complete set is built before the
    ``streak_limit`` cap is enforced, so an over-limit query raises
    :class:`ValueError` without returning partial records.
    """
    type_order = {"node": 0, "edge": 1, "gap": 2}
    # Key -> ordered list of (segment position, change) it appears in.
    per_identity: dict[
        tuple[str, object], list[tuple[int, dict[str, object]]]
    ] = {}
    encounter: dict[tuple[str, object], int] = {}
    next_encounter = 0
    for position, changes in enumerate(segment_changes):
        for change in changes:
            type_name = change["kind"].split("_", 1)[0]
            key = (type_name, change["identity"])
            if key not in encounter:
                encounter[key] = next_encounter
                next_encounter += 1
            per_identity.setdefault(key, []).append((position, change))

    records: list[dict[str, object]] = []
    for key, entries in per_identity.items():
        type_name, identity = key
        run: list[tuple[int, dict[str, object]]] = []

        def flush(run_entries: list[tuple[int, dict[str, object]]]) -> None:
            added_count = 0
            removed_count = 0
            changed_count = 0
            evidence: list[dict[str, object]] = []
            for run_position, change in run_entries:
                kind = change["kind"]
                if kind.endswith("_added"):
                    added_count += 1
                elif kind.endswith("_removed"):
                    removed_count += 1
                else:
                    changed_count += 1
                before = change["before"]
                after = change["after"]
                evidence.append(
                    {
                        "from": run_position,
                        "to": run_position + 1,
                        "kind": kind,
                        "before": (
                            None
                            if before is None
                            else BranchStore._copy_lifetime_record(before)
                        ),
                        "after": (
                            None
                            if after is None
                            else BranchStore._copy_lifetime_record(after)
                        ),
                    }
                )
            records.append(
                {
                    "type": type_name,
                    "identity": BranchStore._freeze_lifetime_value(
                        identity
                    ),
                    "from": run_entries[0][0],
                    "to": run_entries[-1][0] + 1,
                    "segments": len(run_entries),
                    "added": added_count,
                    "removed": removed_count,
                    "changed": changed_count,
                    "changes": tuple(evidence),
                }
            )

        for entry in entries:
            if run and entry[0] != run[-1][0] + 1:
                flush(run)
                run = []
            run.append(entry)
        if run:
            flush(run)

    records.sort(
        key=lambda record: (
            -(
                record["added"]
                + record["removed"]
                + record["changed"]
            ),
            record["from"],
            record["to"],
            type_order[record["type"]],
            encounter[(record["type"], record["identity"])],
        )
    )
    if len(records) > streak_limit_value:
        raise ValueError(
            f"lifetime churn streak limit exceeded: {len(records)} "
            f"streak records, limit is {streak_limit_value}"
        )

    total_added = 0
    total_removed = 0
    total_changed = 0
    for record in records:
        total_added += record["added"]
        total_removed += record["removed"]
        total_changed += record["changed"]
    return {
        "streaks": tuple(records),
        "totals": {
            "streaks": len(records),
            "identities": len(per_identity),
            "added": total_added,
            "removed": total_removed,
            "changed": total_changed,
        },
    }

